from pathlib import Path
p=Path('work/qrh-campaign/agents/integration/build_project.py')
s=p.read_text()
s=s.replace('import argparse, os, re, subprocess, sys, time', 'import argparse, hashlib, json, os, re, subprocess, sys, time')
s=s.replace("env['LEAN_PATH']=';'.join([str(ARTIFACTS)]+[str(p/'.lake/build/lib/lean') for p in PACKAGES.iterdir() if p.is_dir()])", "package_paths = [PACKAGES / 'mathlib'] + sorted(p for p in PACKAGES.iterdir() if p.is_dir() and p.name != 'mathlib')\nenv['LEAN_PATH'] = ';'.join([str(ARTIFACTS)] + [str(p / '.lake/build/lib/lean') for p in package_paths])")
s=s.replace("    log=LOGS/(module+'.log')\n", "    log=LOGS/(module+'.log')\n    receipt=LOGS/(module+'.success.json')\n    key={'source_sha256': hashlib.sha256(source.read_bytes()).hexdigest(), 'lean': '4.35.0', 'mathlib': '56a005855ea17e0b0958f73ec801ae140b0a1679'}\n")
s=s.replace("    if output.exists() and log.exists() and output.stat().st_mtime >= max(p.stat().st_mtime for p in inputs):\n        print(f'{index}/{len(ordered)} cached {module}',flush=True); continue", "    key['dependency_times'] = {str(p): p.stat().st_mtime_ns for p in inputs[1:]}\n    cache_is_current = output.exists() and log.exists() and output.stat().st_mtime >= max(p.stat().st_mtime for p in inputs)\n    if cache_is_current and receipt.exists():\n        cache_is_current = json.loads(receipt.read_text()) == key\n    # Preserve successful legacy outputs produced by the earlier live runner.\n    if cache_is_current:\n        print(f'{index}/{len(ordered)} cached {module}',flush=True); continue")
s=s.replace("    with log.open('w',encoding='utf-8') as stream:\n        process=subprocess.run([str(LEAN),'-j','2','-R',str(SOURCE),'-o',str(output),str(source)],cwd=SOURCE,env=env,stdout=stream,stderr=subprocess.STDOUT)", "    staging = output.parent / ('_partial_' + str(os.getpid()))\n    staging.mkdir(exist_ok=True)\n    partial_output = staging / output.name\n    with log.open('w',encoding='utf-8') as stream:\n        process=subprocess.run([str(LEAN),'-j','2','-R',str(SOURCE),'-o',str(partial_output),str(source)],cwd=SOURCE,env=env,stdout=stream,stderr=subprocess.STDOUT)")
s += "\n    # Promote companion artifacts first; publish the main olean last.\n    for artifact in staging.iterdir():\n        if artifact != partial_output:\n            os.replace(artifact, output.parent / artifact.name)\n    os.replace(partial_output, output)\n    staging.rmdir()\n    temporary_receipt = receipt.with_suffix('.tmp')\n    temporary_receipt.write_text(json.dumps(key, indent=2), encoding='utf-8')\n    os.replace(temporary_receipt, receipt)\n"
p.write_text(s)
